export function rejectionError(reason: unknown): Error {
  if (reason instanceof Error) return reason;
  let message = 'Non-Error rejection';
  try {
    message = String(reason);
  } catch {
    // String conversion must not hide the original rejection from onError.
  }
  return new Error(message, {cause: reason});
}
